import numpy as np

def make_input(agent=None, objects=None, rewards=None, prev=None):
    x = np.zeros(500)
    # wall border in channel 3
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                x[(r*10 + c)*5 + 3] = 1
    if agent:
        r, c = agent
        x[(r*10 + c)*5 + 0] = 1
    if objects:
        for r, c in objects:
            x[(r*10 + c)*5 + 1] = 1
    if rewards:
        for r, c in rewards:
            x[(r*10 + c)*5 + 2] = 1
    if prev:
        for r, c in prev:
            x[(r*10 + c)*5 + 4] = 1
    return x

scenarios = [
    ("base",              make_input(agent=(3,4))),
    ("obj_up",            make_input(agent=(3,4), objects=[(2,4)])),
    ("reward_up",         make_input(agent=(3,4), rewards=[(1,4)])),
    ("obj_up_reward_up",  make_input(agent=(3,4), objects=[(2,4)], rewards=[(1,4)])),
    ("obj_on_goal",       make_input(agent=(3,4), objects=[(2,4)], rewards=[(2,4)])),
]

X = np.array([s[1] for s in scenarios])
