import numpy as np

off = {'up':(-1,0),'down':(1,0),'left':(0,-1),'right':(0,1)}
act = {'up':1,'down':2,'left':3,'right':4}

def obs(agent, reward=None, movers=(), prevs=()):
    x = np.zeros((10,10,5))
    x[0,:,3]=1; x[9,:,3]=1; x[:,0,3]=1; x[:,9,3]=1   # wall border
    x[agent[0],agent[1],0]=1                          # agent
    if reward is not None:
        x[reward[0],reward[1],2]=1                    # reward
    for r,c in movers: x[r,c,1]=1                     # moving object / body
    for r,c in prevs:  x[r,c,4]=1                     # previous frame
    return x.reshape(-1)

agents = [(3,4),(4,3),(5,3)]   # all non-hole, interior cells
rows=[]; meta=[]
for a in agents:
    rows.append(obs(a)); meta.append((a,'base',None))
    for d,(dr,dc) in off.items():
        t=(a[0]+dr, a[1]+dc)
        rows.append(obs(a, reward=t));  meta.append((a,'R_'+d, d))
        rows.append(obs(a, movers=[t])); meta.append((a,'M_'+d, d))
        rows.append(obs(a, prevs=[t]));  meta.append((a,'P_'+d, d))

out = forward(np.array(rows))          # single forward pass (39 rows)
base = {a: out[i] for i,(a,tag,d) in enumerate(meta) if tag=='base'}

for i,(a,tag,d) in enumerate(meta):
    if d is None:
        print(a, 'base argmax', int(np.argmax(out[i])), np.round(out[i],1))
        continue
    dl = out[i][act[d]] - base[a][act[d]]
    print(a, tag, 'delta_toward', round(float(dl),2))
